Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: liquidio: Fix off-by-one error in VF setup_nic_devices()
 cleanup

In setup_nic_devices(), the initialization loop jumps to the label
setup_nic_dev_free on failure. The current cleanup loop while(i--)
skip the failing index i, causing a memory leak.

Fix this by changing the loop to iterate from the current index i
down to 0.

Compile tested only. Issue found using code review.

Fixes: 846b46873eeb ("liquidio CN23XX: VF offload features")
Suggested-by: Simon Horman <horms@kernel.org>
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Reviewed-by: Kory Maincent <kory.maincent@bootlin.com>
Link: https://patch.msgid.link/20260128154440.278369-4-zilin@seu.edu.cn
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In the cleanup loop for failed initialization, the original `while (i--)` decrements `i` before executing the loop body, causing the failing index `i` to be skipped and not cleaned up, resulting in a memory leak.

Here is the patch:
  */
 static int setup_nic_devices(struct octeon_device *octeon_dev)
 {
 	int retval, num_iqueues, num_oqueues;
 	u32 resp_size, data_size;
 	struct liquidio_if_cfg_resp *resp;
 	struct octeon_soft_command *sc;
 	union oct_nic_if_cfg if_cfg;
 	struct octdev_props *props;
 	struct net_device *netdev;
 	struct lio_version *vdata;
 	struct lio *lio = NULL;
 	u8 mac[ETH_ALEN], i, j;
 	u32 ifidx_or_pfnum;

 	ifidx_or_pfnum = octeon_dev->pf_num;

 	/* This is to handle link status changes */
 	octeon_register_dispatch_fn(octeon_dev, OPCODE_NIC, OPCODE_NIC_INFO,
 				    lio_nic_info, octeon_dev);

 	/* REQTYPE_RESP_NET and REQTYPE_SOFT_COMMAND do not have free functions.
 	 * They are handled directly.
 	 */
 	octeon_register_reqtype_free_fn(octeon_dev, REQTYPE_NORESP_NET,
 					free_netbuf);

 	octeon_register_reqtype_free_fn(octeon_dev, REQTYPE_NORESP_NET_SG,
 					free_netsgbuf);

 	octeon_register_reqtype_free_fn(octeon_dev, REQTYPE_RESP_NET_SG,
 					free_netsgbuf_with_resp);

 	for (i = 0; i < octeon_dev->ifcount; i++) {
 		resp_size = sizeof(struct liquidio_if_cfg_resp);
 		data_size = sizeof(struct lio_version);
 		sc = (struct octeon_soft_command *)
 			octeon_alloc_soft_command(octeon_dev, data_size,
 						  resp_size, 0);
 		resp = (struct liquidio_if_cfg_resp *)sc->virtrptr;
 		vdata = (struct lio_version *)sc->virtdptr;

 		*((u64 *)vdata) = 0;
 		vdata->major = cpu_to_be16(LIQUIDIO_BASE_MAJOR_VERSION);
 		vdata->minor = cpu_to_be16(LIQUIDIO_BASE_MINOR_VERSION);
 		vdata->micro = cpu_to_be16(LIQUIDIO_BASE_MICRO_VERSION);

 		if_cfg.u64 = 0;

 		if_cfg.s.num_iqueues = octeon_dev->sriov_info.rings_per_vf;
 		if_cfg.s.num_oqueues = octeon_dev->sriov_info.rings_per_vf;
 		if_cfg.s.base_queue = 0;

 		sc->iq_no = 0;

 		octeon_prepare_soft_command(octeon_dev, sc, OPCODE_NIC,
 					    OPCODE_NIC_IF_CFG, 0, if_cfg.u64,
 					    0);

 		init_completion(&sc->complete);
 		sc->sc_status = OCTEON_REQUEST_PENDING;

 		retval = octeon_send_soft_command(octeon_dev, sc);
 		if (retval == IQ_SEND_FAILED) {
 			dev_err(&octeon_dev->pci_dev->dev,
 				"iq/oq config failed status: %x\n", retval);
 			/* Soft instr is freed by driver in case of failure. */
 			octeon_free_soft_command(octeon_dev, sc);
 			return(-EIO);
 		}

 		/* Sleep on a wait queue till the cond flag indicates that the
 		 * response arrived or timed-out.
 		 */
 		retval = wait_for_sc_completion_timeout(octeon_dev, sc, 0);
 		if (retval)
 			return retval;

 		retval = resp->status;
 		if (retval) {
 			dev_err(&octeon_dev->pci_dev->dev,
 				"iq/oq config failed, retval = %d\n", retval);
 			WRITE_ONCE(sc->caller_is_done, true);
 			return -EIO;
 		}

 		snprintf(octeon_dev->fw_info.liquidio_firmware_version,
 			 32, "%s",
 			 resp->cfg_info.liquidio_firmware_version);

 		octeon_swap_8B_data((u64 *)(&resp->cfg_info),
 				    (sizeof(struct liquidio_if_cfg_info)) >> 3);

 		num_iqueues = hweight64(resp->cfg_info.iqmask);
 		num_oqueues = hweight64(resp->cfg_info.oqmask);

 		if (!(num_iqueues) || !(num_oqueues)) {
 			dev_err(&octeon_dev->pci_dev->dev,
 				"Got bad iqueues (%016llx) or oqueues (%016llx) from firmware.\n",
 				resp->cfg_info.iqmask, resp->cfg_info.oqmask);
 			WRITE_ONCE(sc->caller_is_done, true);
 			goto setup_nic_dev_done;
 		}
 		dev_dbg(&octeon_dev->pci_dev->dev,
 			"interface %d, iqmask %016llx, oqmask %016llx, numiqueues %d, numoqueues %d\n",
 			i, resp->cfg_info.iqmask, resp->cfg_info.oqmask,
 			num_iqueues, num_oqueues);

 		netdev = alloc_etherdev_mq(LIO_SIZE, num_iqueues);

 		if (!netdev) {
 			dev_err(&octeon_dev->pci_dev->dev, "Device allocation failed\n");
 			WRITE_ONCE(sc->caller_is_done, true);
 			goto setup_nic_dev_done;
 		}

 		SET_NETDEV_DEV(netdev, &octeon_dev->pci_dev->dev);

 		/* Associate the routines that will handle different
 		 * netdev tasks.
 		 */
 		netdev->netdev_ops = &lionetdevops;

 		lio = GET_LIO(netdev);

 		memset(lio, 0, sizeof(struct lio));

 		lio->ifidx = ifidx_or_pfnum;

 		props = &octeon_dev->props[i];
 		props->gmxport = resp->cfg_info.linfo.gmxport;
 		props->netdev = netdev;

 		lio->linfo.num_rxpciq = num_oqueues;
 		lio->linfo.num_txpciq = num_iqueues;

 		for (j = 0; j < num_oqueues; j++) {
 			lio->linfo.rxpciq[j].u64 =
 			    resp->cfg_info.linfo.rxpciq[j].u64;
 		}
 		for (j = 0; j < num_iqueues; j++) {
 			lio->linfo.txpciq[j].u64 =
 			    resp->cfg_info.linfo.txpciq[j].u64;
 		}

 		lio->linfo.hw_addr = resp->cfg_info.linfo.hw_addr;
 		lio->linfo.gmxport = resp->cfg_info.linfo.gmxport;
 		lio->linfo.link.u64 = resp->cfg_info.linfo.link.u64;
 		lio->linfo.macaddr_is_admin_asgnd =
 			resp->cfg_info.linfo.macaddr_is_admin_asgnd;
 		lio->linfo.macaddr_spoofchk =
 			resp->cfg_info.linfo.macaddr_spoofchk;

 		lio->msg_enable = netif_msg_init(debug, DEFAULT_MSG_ENABLE);

 		lio->dev_capability = NETIF_F_HIGHDMA
 				      | NETIF_F_IP_CSUM | NETIF_F_IPV6_CSUM
 				      | NETIF_F_SG | NETIF_F_RXCSUM
 				      | NETIF_F_TSO | NETIF_F_TSO6
 				      | NETIF_F_GRO
 				      | NETIF_F_LRO;
 		netif_set_tso_max_size(netdev, OCTNIC_GSO_MAX_SIZE);

 		/* Copy of transmit encapsulation capabilities:
 		 * TSO, TSO6, Checksums for this device
 		 */
 		lio->enc_dev_capability = NETIF_F_IP_CSUM
 					  | NETIF_F_IPV6_CSUM
 					  | NETIF_F_GSO_UDP_TUNNEL
 					  | NETIF_F_HW_CSUM | NETIF_F_SG
 					  | NETIF_F_RXCSUM
 					  | NETIF_F_TSO | NETIF_F_TSO6
 					  | NETIF_F_LRO;

 		netdev->hw_enc_features =
 		    (lio->enc_dev_capability & ~NETIF_F_LRO);
 		netdev->udp_tunnel_nic_info = &liquidio_udp_tunnels;

 		netdev->vlan_features = lio->dev_capability;
 		/* Add any unchangeable hw features */
 		lio->dev_capability |= NETIF_F_HW_VLAN_CTAG_FILTER |
 				       NETIF_F_HW_VLAN_CTAG_RX |
 				       NETIF_F_HW_VLAN_CTAG_TX;

 		netdev->features = (lio->dev_capability & ~NETIF_F_LRO);

 		netdev->hw_features = lio->dev_capability;
 		netdev->hw_features &= ~NETIF_F_HW_VLAN_CTAG_RX;

 		/* MTU range: 68 - 16000 */
 		netdev->min_mtu = LIO_MIN_MTU_SIZE;
 		netdev->max_mtu = LIO_MAX_MTU_SIZE;

 		WRITE_ONCE(sc->caller_is_done, true);

 		/* Point to the  properties for octeon device to which this
 		 * interface belongs.
 		 */
 		lio->oct_dev = octeon_dev;
 		lio->octprops = props;
 		lio->netdev = netdev;

 		dev_dbg(&octeon_dev->pci_dev->dev,
 			"if%d gmx: %d hw_addr: 0x%llx\n", i,
 			lio->linfo.gmxport, CVM_CAST64(lio->linfo.hw_addr));

 		/* 64-bit swap required on LE machines */
 		octeon_swap_8B_data(&lio->linfo.hw_addr, 1);
 		for (j = 0; j < ETH_ALEN; j++)
 			mac[j] = *((u8 *)(((u8 *)&lio->linfo.hw_addr) + 2 + j));

 		/* Copy MAC Address to OS network device structure */
 		eth_hw_addr_set(netdev, mac);

 		if (liquidio_setup_io_queues(octeon_dev, i,
 					     lio->linfo.num_txpciq,
 					     lio->linfo.num_rxpciq)) {
 			dev_err(&octeon_dev->pci_dev->dev, "I/O queues creation failed\n");
 			goto setup_nic_dev_free;
 		}

 		ifstate_set(lio, LIO_IFSTATE_DROQ_OPS);

 		/* For VFs, enable Octeon device interrupts here,
 		 * as this is contingent upon IO queue setup
 		 */
 		octeon_dev->fn_list.enable_interrupt(octeon_dev,
 						     OCTEON_ALL_INTR);

 		/* By default all interfaces on a single Octeon uses the same
 		 * tx and rx queues
 		 */
 		lio->txq = lio->linfo.txpciq[0].s.q_no;
 		lio->rxq = lio->linfo.rxpciq[0].s.q_no;

 		lio->tx_qsize = octeon_get_tx_qsize(octeon_dev, lio->txq);
 		lio->rx_qsize = octeon_get_rx_qsize(octeon_dev, lio->rxq);

 		if (lio_setup_glists(octeon_dev, lio, num_iqueues)) {
 			dev_err(&octeon_dev->pci_dev->dev,
 				"Gather list allocation failed\n");
 			goto setup_nic_dev_free;
 		}

 		/* Register ethtool support */
 		liquidio_set_ethtool_ops(netdev);
 		if (lio->oct_dev->chip_id == OCTEON_CN23XX_VF_VID)
 			octeon_dev->priv_flags = OCT_PRIV_FLAG_DEFAULT;
 		else
 			octeon_dev->priv_flags = 0x0;

 		if (netdev->features & NETIF_F_LRO)
 			liquidio_set_feature(netdev, OCTNET_CMD_LRO_ENABLE,
 					     OCTNIC_LROIPV4 | OCTNIC_LROIPV6);

 		if (setup_link_status_change_wq(netdev))
 			goto setup_nic_dev_free;

 		if (setup_rx_oom_poll_fn(netdev))
 			goto setup_nic_dev_free;

 		/* Register the network device with the OS */
 		if (register_netdev(netdev)) {
 			dev_err(&octeon_dev->pci_dev->dev, "Device registration failed\n");
 			goto setup_nic_dev_free;
 		}

 		dev_dbg(&octeon_dev->pci_dev->dev,
 			"Setup NIC ifidx:%d mac:%02x%02x%02x%02x%02x%02x\n",
 			i, mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
 		netif_carrier_off(netdev);
 		lio->link_changes++;

 		ifstate_set(lio, LIO_IFSTATE_REGISTERED);

 		/* Sending command to firmware to enable Rx checksum offload
 		 * by default at the time of setup of Liquidio driver for
 		 * this device
 		 */
 		liquidio_set_rxcsum_command(netdev, OCTNET_CMD_TNL_RX_CSUM_CTL,
 					    OCTNET_CMD_RXCSUM_ENABLE);
 		liquidio_set_feature(netdev, OCTNET_CMD_TNL_TX_CSUM_CTL,
 				     OCTNET_CMD_TXCSUM_ENABLE);

 		dev_dbg(&octeon_dev->pci_dev->dev,
 			"NIC ifidx:%d Setup successful\n", i);

 		octeon_dev->no_speed_setting = 1;
 	}

 	return 0;

 setup_nic_dev_free:

-	while (i--) {
+	do {
 		dev_err(&octeon_dev->pci_dev->dev,
 			"NIC ifidx:%d Setup failed\n", i);
 		liquidio_destroy_nic_device(octeon_dev, i);
-	}
+	} while (i--);

 setup_nic_dev_done:

 	return -ENODEV;
 }



